{"command":"python3 - << 'PY'
import subprocess, os, pty, struct, fcntl, termios
def run(args, inp=b"hi", env=None):
    e=dict(os.environ); 
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    p=subprocess.run(["./executable"]+args, input=inp, capture_output=True, env=e)
    return p.stdout.decode(), p.stderr.decode(), p.returncode

for mode in ["always","auto","never","force"]:
    out,_,_=run(["--color",mode])
    print(mode,"pipe esc?", "\x1b" in out)
    out,_,_=run(["--color",mode], env={"NO_COLOR":"1"})
    print(mode,"pipe+NO_COLOR esc?", "\x1b" in out)

# CLICOLOR ?
for var in ["CLICOLOR","CLICOLOR_FORCE","TERM"]:
    for val in ["0","1","dumb"]:
        out,_,_=run([], env={var:val})
        print(var,val, "\x1b" in out)
        out,_,_=run(["--color=auto"], env={var:val})
        print(" auto",var,val, "\x1b" in out)

# pty auto
def run_pty(cols, args, inp=b"hi", env=None):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols, 0, 0))
    e=dict(os.environ)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    p=subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=e, close_fds=True)
    os.close(slave)
    p.stdin.write(inp); p.stdin.close()
    out=b""
    while True:
        try:
            d=os.read(master,8192)
            if not d: break
            out+=d
        except OSError: break
    p.wait(); os.close(master)
    return out.decode()
for mode in ["always","auto","never","force"]:
    out=run_pty(80, ["--color",mode])
    print("pty",mode, "\x1b" in out)
    out=run_pty(80, ["--color",mode], env={"NO_COLOR":"1"})
    print("pty NO_COLOR",mode, "\x1b" in out)
for var,val in [("TERM","dumb"),("CLICOLOR","0")]:
    out=run_pty(80, ["--color=auto"], env={var:val})
    print("pty auto",var,val, "\x1b" in out)
    out=run_pty(80, [], env={var:val})
    print("pty default",var,val, "\x1b" in out)
PY"}

