import subprocess, os, pty, struct, fcntl, termios

def run_pipe(args, env):
    e={"PATH":os.environ["PATH"]}
    e.update(env)
    p=subprocess.run(["./executable"]+args, input=b"A", capture_output=True, env=e)
    return "\x1b" in p.stdout.decode()

def run_pty(args, env, cols=80):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols, 0, 0))
    e={"PATH":os.environ["PATH"]}; e.update(env)
    p=subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=e, close_fds=True)
    os.close(slave)
    p.stdin.write(b"A"); p.stdin.close()
    out=b""
    while True:
        try:
            d=os.read(master,8192)
            if not d: break
            out+=d
        except OSError: break
    p.wait(); os.close(master)
    return "\x1b" in out.decode()

