// ---------- configuration ----------

#[derive(Clone, Copy, PartialEq, Eq)]
enum Base {
    Binary,
    Octal,
    Decimal,
    Hexadecimal,
}

impl Base {
    fn digits(&self) -> usize {
        match self {
            Base::Binary => 8,
            Base::Octal => 3,
            Base::Decimal => 3,
            Base::Hexadecimal => 2,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum BorderStyle {
    Unicode,
    Ascii,
    None,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ColorScheme {
    Default,
    Gradient,
}

struct PrinterConfig {
    panels: usize,
    group_size: usize,
    little_endian: bool,
    base: Base,
    show_position: bool,
    show_characters: bool,
    border: BorderStyle,
    use_color: bool,
    colors: ColourConfig,
    scheme: ColorScheme,
    character_table: CharacterTable,
}

impl PrinterConfig {
    fn panel_width(&self) -> usize {
        8 * self.base.digits() + 8 / self.group_size + 1
    }
    fn empty_panel_width(&self) -> usize {
        // Width used by the header / "No content" rendering when there is no data.
        8 * 2 + 8 / self.group_size + 1
    }
    fn byte_color_code(&self, byte: u8) -> String {
        match self.scheme {
            ColorScheme::Gradient => {
                let (r, g, b) = GRADIENT_TABLE[byte as usize];
                format!("38;2;{:03};{:03};{:03}", r, g, b)
            }
            ColorScheme::Default => {
                if byte == 0 {
                    self.colors.null.clone()
                } else if byte.is_ascii_whitespace() {
                    self.colors.whitespace.clone()
                } else if byte.is_ascii_graphic() {
                    self.colors.printable.clone()
                } else if byte < 0x80 {
                    self.colors.other.clone()
                } else {
                    self.colors.nonascii.clone()
                }
            }
        }
    }
}

// ---------- output writing ----------

fn write_stdout(text: &str) -> AppResult<()> {
    let stdout = io::stdout();
    let mut handle = stdout.lock();
    match handle.write_all(text.as_bytes()) {
        Ok(()) => {
            let _ = handle.flush();
            Ok(())
        }
        Err(e) => {
            if e.kind() == io::ErrorKind::BrokenPipe {
                Ok(())
            } else {
                Err(Failure::io(&e))
            }
        }
    }
}

// ---------- printer ----------

fn border_chars(style: BorderStyle) -> (char, char, char) {
    // (main separator, interior separator, fill character for border lines)
    match style {
        BorderStyle::Unicode => ('│', '┊', '─'),
        BorderStyle::Ascii => ('|', '|', '-'),
        BorderStyle::None => (' ', ' ', ' '),
    }
}

fn border_line(cfg: &PrinterConfig, top: bool, empty_mode: bool) -> String {
    let hex_width = if empty_mode { cfg.empty_panel_width() } else { cfg.panel_width() };
    let mut segments: Vec<usize> = Vec::new();
    if cfg.show_position {
        segments.push(8);
    }
    for _ in 0..cfg.panels {
        segments.push(hex_width);
    }
    if cfg.show_characters {
        for _ in 0..cfg.panels {
            segments.push(8);
        }
    }
    let (left, join, right, fill) = match cfg.border {
        BorderStyle::Unicode => {
            if top {
                ('┌', '┬', '┐', '─')
            } else {
                ('└', '┴', '┘', '─')
            }
        }
        BorderStyle::Ascii => ('+', '+', '+', '-'),
        BorderStyle::None => (' ', ' ', ' ', ' '),
    };
    let mut out = String::new();
    out.push(left);
    for (i, seg) in segments.iter().enumerate() {
        if i > 0 {
            out.push(join);
        }
        for _ in 0..*seg {
            out.push(fill);
        }
    }
    out.push(right);
    out
}

fn no_content_line(cfg: &PrinterConfig) -> String {
    let w = cfg.empty_panel_width();
    let mut segments: Vec<String> = Vec::new();
    if cfg.show_position {
        segments.push(" ".repeat(8));
    }
    let first = format!("{:<width$}", " No content", width = w);
    segments.push(first);
    segments.push(" ".repeat(w));
    if cfg.show_characters {
        segments.push(" ".repeat(8));
        segments.push(" ".repeat(8));
    }
    format!("│{}│", segments.join("│"))
}

fn format_byte(byte: u8, base: Base) -> String {
    match base {
        Base::Hexadecimal => format!("{:02x}", byte),
        Base::Octal => format!("{:03o}", byte),
        Base::Decimal => format!("{:03}", byte),
        Base::Binary => format!("{:08b}", byte),
    }
}

fn panel_bytes<'a>(chunk: &'a [u8], panel: usize, cfg: &PrinterConfig) -> &'a [u8] {
    let start = panel * 8;
    if start >= chunk.len() {
        &[]
    } else {
        let end = usize::min(start + 8, chunk.len());
        &chunk[start..end]
    }
}

// Build the (text, colour-per-token) representation of a hex panel.
fn hex_tokens(cfg: &PrinterConfig, bytes: &[u8]) -> Vec<(u8, String)> {
    let mut tokens: Vec<(u8, String)> = Vec::new();
    if bytes.is_empty() {
        return tokens;
    }
    let groups: Vec<&[u8]> = bytes.chunks(cfg.group_size).collect();
    let group_count = groups.len();
    for (gi, group) in groups.iter().enumerate() {
        // Displayed order within the group.
        let displayed: Vec<u8> = if cfg.little_endian {
            group.iter().rev().copied().collect()
        } else {
            group.to_vec()
        };
        for (i, b) in displayed.iter().enumerate() {
            let mut text = format_byte(*b, cfg.base);
            if i + 1 == displayed.len() && gi + 1 != group_count {
                text.push(' ');
            }
            tokens.push((*b, text));
        }
    }
    tokens
}

fn hex_text(cfg: &PrinterConfig, bytes: &[u8]) -> String {
    hex_tokens(cfg, bytes).into_iter().map(|(_, t)| t).collect()
}

fn hex_panel(cfg: &PrinterConfig, bytes: &[u8], panel_index: usize) -> String {
    let w = cfg.panel_width();
    let inner = w - 2;
    if !cfg.use_color {
        let text = hex_text(cfg, bytes);
        return format!(" {:<width$} ", text, width = inner);
    }
    let mut out = String::new();
    if panel_index == 0 && !cfg.show_position {
        out.push_str(&format!("\x1b[{}m ", cfg.colors.offset));
    } else {
        out.push(' ');
    }
    let tokens = hex_tokens(cfg, bytes);
    let text_len: usize = tokens.iter().map(|(_, t)| t.chars().count()).sum();
    let mut current: Option<String> = None;
    for (byte, text) in tokens.iter() {
        let code = cfg.byte_color_code(*byte);
        if current.as_deref() != Some(code.as_str()) {
            out.push_str(&format!("\x1b[{}m", code));
            current = Some(code);
        }
        out.push_str(text);
    }
    let pad = inner.saturating_sub(text_len);
    for _ in 0..pad {
        out.push(' ');
    }
    out.push_str("\x1b[39m ");
    out
}

fn empty_hex_panel(cfg: &PrinterConfig) -> String {
    let w = cfg.panel_width();
    if !cfg.use_color {
        return " ".repeat(w);
    }
    let inner = w - 2;
    let mut out = String::new();
    out.push(' ');
    for _ in 0..inner {
        out.push(' ');
    }
    out.push_str("\x1b[39m ");
    out
}

fn char_panel(cfg: &PrinterConfig, bytes: &[u8]) -> String {
    if !cfg.use_color {
        let mut text = String::new();
        for b in bytes {
            text.push(map_char(cfg.character_table, *b));
        }
        return format!("{:<width$}", text, width = 8);
    }
    let mut out = String::new();
    let mut current: Option<String> = None;
    for b in bytes {
        let code = cfg.byte_color_code(*b);
        if current.as_deref() != Some(code.as_str()) {
            out.push_str(&format!("\x1b[{}m", code));
            current = Some(code);
        }
        out.push(map_char(cfg.character_table, *b));
    }
    let pad = 8usize.saturating_sub(bytes.len());
    for _ in 0..pad {
        out.push(' ');
    }
    out.push_str("\x1b[39m");
    out
}

fn empty_char_panel(cfg: &PrinterConfig) -> String {
    if !cfg.use_color {
        " ".repeat(8)
    } else {
        "        \x1b[39m".to_string()
    }
}

fn position_segment(cfg: &PrinterConfig, offset: u64) -> String {
    let text = format!("{:08x}", offset);
    if cfg.use_color {
        format!("\x1b[{}m{}\x1b[39m", cfg.colors.offset, text)
    } else {
        text
    }
}

fn assemble_line(cfg: &PrinterConfig, pos: Option<String>, hex_panels: Vec<String>, char_panels: Option<Vec<String>>) -> String {
    let (main, mid, _) = border_chars(cfg.border);
    let mut out = String::new();
    out.push(main);
    if let Some(p) = pos {
        out.push_str(&p);
        out.push(main);
    }
    for (i, panel) in hex_panels.iter().enumerate() {
        if i > 0 {
            out.push(mid);
        }
        out.push_str(panel);
    }
    out.push(main);
    if let Some(chars) = char_panels {
        for (i, panel) in chars.iter().enumerate() {
            if i > 0 {
                out.push(mid);
            }
            out.push_str(panel);
        }
        out.push(main);
    }
    out
}

fn data_line(cfg: &PrinterConfig, chunk: &[u8], offset: u64) -> String {
    let pos = if cfg.show_position {
        Some(position_segment(cfg, offset))
    } else {
        None
    };
    let mut hex_panels = Vec::new();
    for i in 0..cfg.panels {
        hex_panels.push(hex_panel(cfg, panel_bytes(chunk, i, cfg), i));
    }
    let char_panels = if cfg.show_characters {
        let mut v = Vec::new();
        for i in 0..cfg.panels {
            v.push(char_panel(cfg, panel_bytes(chunk, i, cfg)));
        }
        Some(v)
    } else {
        None
    };
    assemble_line(cfg, pos, hex_panels, char_panels)
}

fn empty_data_line(cfg: &PrinterConfig, offset: u64) -> String {
    let pos = if cfg.show_position {
        Some(position_segment(cfg, offset))
    } else {
        None
    };
    let hex_panels: Vec<String> = (0..cfg.panels).map(|_| empty_hex_panel(cfg)).collect();
    let char_panels = if cfg.show_characters {
        Some((0..cfg.panels).map(|_| empty_char_panel(cfg)).collect())
    } else {
        None
    };
    assemble_line(cfg, pos, hex_panels, char_panels)
}

fn star_line(cfg: &PrinterConfig) -> String {
    if cfg.show_position {
        let pos = if cfg.use_color {
            format!("\x1b[{}m*\x1b[39m       ", cfg.colors.offset)
        } else {
            "*       ".to_string()
        };
        let hex_panels: Vec<String> = (0..cfg.panels).map(|_| empty_hex_panel(cfg)).collect();
        let char_panels = if cfg.show_characters {
            Some((0..cfg.panels).map(|_| empty_char_panel(cfg)).collect())
        } else {
            None
        };
        return assemble_line(cfg, Some(pos), hex_panels, char_panels);
    }
    // Without a position panel, the asterisk lands in the first hex panel.
    let w = cfg.panel_width();
    let first = if cfg.use_color {
        format!(
            "\x1b[{0}m\x1b[{0}m*\x1b[39m{1}\x1b[39m ",
            cfg.colors.offset,
            " ".repeat(w - 2)
        )
    } else {
        format!("*{}", " ".repeat(w - 1))
    };
    let mut hex_panels: Vec<String> = vec![first];
    for _ in 1..cfg.panels {
        hex_panels.push(empty_hex_panel(cfg));
    }
    let char_panels = if cfg.show_characters {
        Some((0..cfg.panels).map(|_| empty_char_panel(cfg)).collect())
    } else {
        None
    };
    assemble_line(cfg, None, hex_panels, char_panels)
}

// ---------- main logic ----------

enum InputKind {
    File(File),
    Stdin,
}

fn run(matches: &clap::ArgMatches) -> AppResult<()> {
    let colors = ColourConfig::from_env();

    if matches.get_flag("print-color-table") {
        return write_stdout(&colour_table_string(&colors));
    }

    if let Some(shell) = matches.get_one::<String>("completion") {
        let text = match shell.as_str() {
            "bash" => include_str!("../completions/bash"),
            "elvish" => include_str!("../completions/elvish"),
            "fish" => include_str!("../completions/fish"),
            "powershell" => include_str!("../completions/powershell"),
            "zsh" => include_str!("../completions/zsh"),
            _ => "",
        };
        return write_stdout(text);
    }

    // Open the input.
    let file_path: Option<PathBuf> = matches.get_one::<PathBuf>("FILE").cloned();
    let mut input_kind: InputKind;
    if let Some(path) = &file_path {
        let metadata = std::fs::metadata(path).map_err(|e| Failure::io(&e))?;
        if metadata.is_dir() {
            return Err(Failure::single(format!("'{}' is a directory.", path.display())));
        }
        let file = File::open(path).map_err(|e| Failure::io(&e))?;
        input_kind = InputKind::File(file);
    } else {
        input_kind = InputKind::Stdin;
    }

    // Block size.
    let block_arg = matches.get_one::<String>("block-size").map(|s| s.as_str()).unwrap_or("512");
    let block_size_i64 = parse_block_size(block_arg)?;
    if block_size_i64 == 0 {
        return Err(Failure::single("block size argument must be positive".to_string()));
    }
    if block_arg.starts_with("0x") {
        // A block size written in hexadecimal silently exits, as in the
        // reference implementation.
        return Ok(());
    }
    let block_size = block_size_i64;

    // Skip.
    let mut byte_position: u64 = 0;
    let mut skip_forward: u64 = 0;
    let mut did_seek_from_end = false;
    if let Some(skip_arg) = matches.get_one::<String>("skip") {
        let signed = parse_signed(skip_arg, block_size)
            .map_err(|e| with_parse_context("--skip", skip_arg, e))?;
        if signed.negative {
            match &mut input_kind {
                InputKind::Stdin => {
                    return Err(Failure::single(
                        "Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).".to_string(),
                    ));
                }
                InputKind::File(file) => {
                    match file.seek(SeekFrom::End(-signed.magnitude)) {
                        Ok(pos) => {
                            byte_position = pos;
                            did_seek_from_end = true;
                        }
                        Err(_) => {
                            return Err(Failure::single(
                                "Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).".to_string(),
                            ));
                        }
                    }
                }
            }
        } else {
            byte_position = signed.magnitude as u64;
            skip_forward = signed.magnitude as u64;
        }
    }

    // Length.
    let length_opt: Option<u64> = if let Some(len_arg) = matches.get_one::<String>("length") {
        Some(parse_unsigned_arg("--length", len_arg, block_size)? as u64)
    } else {
        None
    };

    // Display offset.
    let display_arg = matches.get_one::<String>("display-offset").map(|s| s.as_str()).unwrap_or("0");
    let display_offset = parse_unsigned_arg("--display-offset", display_arg, block_size)? as u64;

    // Base.
    let base_arg = matches.get_one::<String>("base").map(|s| s.as_str()).unwrap_or("hexadecimal");
    let base = match base_arg {
        "b" | "bin" | "binary" | "2" => Base::Binary,
        "o" | "oct" | "octal" | "8" => Base::Octal,
        "d" | "dec" | "decimal" | "10" => Base::Decimal,
        "x" | "hex" | "hexadecimal" | "16" => Base::Hexadecimal,
        _ => {
            return Err(Failure::single(
                "The base provided is not valid. Valid bases are \"b\", \"o\", \"d\", and \"x\".".to_string(),
            ));
        }
    };

    // Plain / display options.
    let plain = matches.get_flag("plain");
    let show_position = !plain && !matches.get_flag("no-position");
    let show_characters = if plain {
        false
    } else if matches.get_flag("characters") {
        true
    } else if matches.get_flag("no-characters") {
        false
    } else {
        true
    };

    let group_size: usize = matches
        .get_one::<String>("group-size")
        .map(|s| s.parse::<usize>().unwrap_or(1))
        .unwrap_or(1);

    let character_table = match matches.get_one::<String>("character-table").map(|s| s.as_str()) {
        Some("ascii") => CharacterTable::Ascii,
        Some("codepage-1047") => CharacterTable::Codepage1047,
        Some("codepage-437") => CharacterTable::Codepage437,
        Some("braille") => CharacterTable::Braille,
        _ => CharacterTable::Default,
    };

    let scheme = match matches.get_one::<String>("color-scheme").map(|s| s.as_str()) {
        Some("gradient") => ColorScheme::Gradient,
        _ => ColorScheme::Default,
    };

    // Panels.
    let panel_width_for_calc = 8 * base.digits() + 8 / group_size + 1;
    let cost = panel_width_for_calc + 1 + if show_characters { 8 } else { 0 };
    let overhead: usize = if show_position { 10 } else { 1 };
    let max_panels_for = |width: usize| -> usize {
        let avail = width.saturating_sub(overhead);
        let n = avail / cost;
        if n == 0 { 1 } else { n }
    };

    let panels: usize = if let Some(panels_arg) = matches.get_one::<String>("panels") {
        if panels_arg == "auto" {
            max_panels_for(terminal_width())
        } else {
            match panels_arg.parse::<NonZeroUsize>() {
                Ok(v) => v.get(),
                Err(e) => {
                    return Err(Failure::chain(vec![
                        format!("failed to parse `--panels` arg \"{}\" as unsigned nonzero integer", panels_arg),
                        format!("{}", e),
                    ]));
                }
            }
        }
    } else if let Some(tw) = matches.get_one::<NonZeroUsize>("terminal-width") {
        max_panels_for(tw.get())
    } else {
        let m = max_panels_for(terminal_width());
        if m > 2 { 2 } else { m }
    };

    // Border / colour resolution (explicit options win over --plain).
    let border = match matches.get_one::<String>("border").map(|s| s.as_str()) {
        Some("ascii") => BorderStyle::Ascii,
        Some("none") => BorderStyle::None,
        Some("unicode") => BorderStyle::Unicode,
        Some(_) => BorderStyle::Unicode,
        None => {
            if plain {
                BorderStyle::None
            } else {
                BorderStyle::Unicode
            }
        }
    };

    let color_arg: Option<String> = matches.get_one::<String>("color").cloned();
    let use_color = match color_arg.as_deref() {
        Some("never") => false,
        Some("always") => env::var_os("NO_COLOR").is_none(),
        Some("force") => true,
        Some("auto") => auto_colour_enabled(),
        Some(_) => false,
        None => {
            if plain {
                false
            } else {
                env::var_os("NO_COLOR").is_none()
            }
        }
    };

    let little_endian = if matches.get_flag("e") {
        true
    } else {
        matches.get_one::<String>("endianness").map(|s| s.as_str()) == Some("little")
    };

    let cfg = PrinterConfig {
        panels,
        group_size,
        little_endian,
        base,
        show_position,
        show_characters,
        border,
        use_color,
        colors,
        scheme,
        character_table,
    };

    // Obtain a reader.
    let mut reader: Box<dyn Read> = match input_kind {
        InputKind::File(f) => Box::new(f),
        InputKind::Stdin => Box::new(io::stdin()),
    };

    // Discard a positive skip amount by reading.
    if !did_seek_from_end && skip_forward > 0 {
        let mut remaining = skip_forward;
        let mut buf = [0u8; 8192];
        while remaining > 0 {
            let want = usize::min(remaining as usize, buf.len());
            match reader.read(&mut buf[..want]) {
                Ok(0) => break,
                Ok(n) => remaining -= n as u64,
                Err(e) => return Err(Failure::io(&e)),
            }
        }
    }

    // Read the remaining input (bounded by --length).
    let mut data: Vec<u8> = Vec::new();
    {
        let limit = length_opt.unwrap_or(u64::MAX);
        let mut limited = reader.take(limit);
        limited.read_to_end(&mut data).map_err(|e| Failure::io(&e))?;
    }

    let start_offset = byte_position.wrapping_add(display_offset);

    if matches.get_flag("include") {
        if data.is_empty() {
            return write_stdout("\n");
        }
        let mut out = String::new();
        let total = data.len();
        for (i, b) in data.iter().enumerate() {
            if i % 12 == 0 {
                out.push_str("  ");
            }
            out.push_str(&format!("0x{:02x}", b));
            if i + 1 != total {
                out.push(',');
                if i % 12 == 11 {
                    out.push('\n');
                } else {
                    out.push(' ');
                }
            } else {
                out.push('\n');
            }
        }
        return write_stdout(&out);
    }

    // Regular hex view.
    let mut out = String::new();
    if data.is_empty() {
        if cfg.border != BorderStyle::None {
            out.push_str(&border_line(&cfg, true, true));
            out.push('\n');
        }
        out.push_str(&no_content_line(&cfg));
        out.push('\n');
        if cfg.border != BorderStyle::None {
            out.push_str(&border_line(&cfg, false, true));
            out.push('\n');
        }
        return write_stdout(&out);
    }

    if cfg.border != BorderStyle::None {
        out.push_str(&border_line(&cfg, true, false));
        out.push('\n');
    }

    let row_len = cfg.panels.saturating_mul(8).max(1);
    let no_squeezing = matches.get_flag("no-squeezing");
    let mut prev_chunk: Option<&[u8]> = None;
    let mut squeezing = false;
    let mut offset = start_offset;

    for chunk in data.chunks(row_len) {
        let duplicate = !no_squeezing
            && chunk.len() == row_len
            && prev_chunk.map_or(false, |prev| prev == chunk)
            && chunk.iter().all(|b| *b == chunk[0]);
        if duplicate {
            if !squeezing {
                out.push_str(&star_line(&cfg));
                out.push('\n');
                squeezing = true;
            }
        } else {
            squeezing = false;
            out.push_str(&data_line(&cfg, chunk, offset));
            out.push('\n');
        }
        prev_chunk = Some(chunk);
        offset = offset.wrapping_add(chunk.len() as u64);
    }

    if squeezing {
        if cfg.show_position {
            out.push_str(&empty_data_line(&cfg, offset));
            out.push('\n');
        } else {
            out.push_str(&star_line(&cfg));
            out.push('\n');
        }
    }

    if cfg.border != BorderStyle::None {
        out.push_str(&border_line(&cfg, false, false));
        out.push('\n');
    }

    write_stdout(&out)
}

fn main() {
    let matches = build_command().get_matches();
    match run(&matches) {
        Ok(()) => {}
        Err(e) => {
            e.print();
            std::process::exit(1);
        }
    }
}
