//! Minimal terminal-size helper used by the command-line parser to wrap help
//! text. It reports the size of the first standard stream that is attached
//! to a terminal.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

fn size_for_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 {
            return Some((Width(ws.ws_col), Height(ws.ws_row)));
        }
    }
    None
}

/// Returns the size of the terminal attached to a standard stream, if any.
pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        if let Some(size) = size_for_fd(fd) {
            return Some(size);
        }
    }
    None
}
