import subprocess, os, itertools, random
ORIG="./executable"; NEW="/tmp/newbin/executable"
def run(bin,args,inp=b"",env=None,cwd=None):
    e=dict(os.environ)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    p=subprocess.run([bin]+args, input=inp, capture_output=True, env=e, cwd=cwd)
    return p.returncode,p.stdout,p.stderr
fails=0; total=0
def check(args,inp=b"",env=None,cwd=None):
