    def make(mode):
        if mode=='pty':
            m,s=pty.openpty(); fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH",24,cols,0,0)); return m,s
        return None, subprocess.PIPE
    mo,so=make(stdout_mode); me,se=make(stderr_mode); mi,si=make(stdin_mode)
    e=dict(os.environ)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    p=subprocess.Popen([binpath]+args, stdin=si, stdout=so, stderr=se, env=e)
    for s in [so,se,si]:
        if s not in (subprocess.PIPE,None):
            try: os.close(s)
            except: pass
