        match base_arg {
            "b" | "bin" | "binary" => Base::Binary,
            "o" | "oct" | "octal" => Base::Octal,
            "d" | "dec" | "decimal" => Base::Decimal,
            "x" | "hex" | "hexadecimal" => Base::Hexadecimal,
            _ => {
                return Err(Failure::single(
                    "The base provided is not valid. Valid bases are \\"b\\", \\"o\\", \\"d\\", and \\"x\\".".to_string(),
                ));
            }
        }
    };

'''
s=s[:old_start]+new_block+s[old_end:]
