def run(binpath, outcols, errcols):
    mo,so=pty.openpty(); fcntl.ioctl(so, termios.TIOCSWINSZ, struct.pack("HHHH",24,outcols,0,0))
    me,se=pty.openpty(); fcntl.ioctl(se, termios.TIOCSWINSZ, struct.pack("HHHH",24,errcols,0,0))
