    os.close(so); os.close(se); p.stdin.close()
    def read(m):
        d=b""
        while True:
            try:
                x=os.read(m,8192)
                if not x: break
                d+=x
            except: break
        os.close(m); return d
    out=read(mo); err=read(me); p.wait(); return len(out.decode().splitlines()[0])
for oc,ec in [(0,40),(0,120),(10,120),(40,120)]:
